const PlaygroundSource = "import { ToggleGroup, ToggleGroupItem } from \"@/registry/erbium/ui/toggle-group\";\nimport type * as React from \"react\";\n\nconst Example = (args: React.ComponentProps<typeof ToggleGroup>) => (\n  <ToggleGroup {...args}>\n    <ToggleGroupItem value=\"one\">One</ToggleGroupItem>\n    <ToggleGroupItem value=\"two\">Two</ToggleGroupItem>\n    <ToggleGroupItem value=\"three\">Three</ToggleGroupItem>\n  </ToggleGroup>\n);\n\nexport default Example;\n";

